function isOwner(invoice, session) {
  return invoice.ownerId === session.userId;
}

function findInvoice(invoices, id) {
  return invoices.find((inv) => inv.id === id) || null;
}

function ownedBy(invoices, userId) {
  return invoices.filter((inv) => inv.ownerId === userId).map((inv) => inv.id);
}

function canRead(session, invoice) {
  return Boolean(session && session.userId) && invoice.ownerId === session.userId;
}

function countOwned(invoices, userId) {
  return invoices.filter((inv) => inv.ownerId === userId).length;
}

function totalOwned(invoices, userId) {
  let sum = 0;
  for (const inv of invoices) {
    if (inv.ownerId === userId) sum += inv.total;
  }
  return sum;
}

function accessStatus(session, invoice) {
  if (!session || !session.userId) return "unauthenticated";
  if (invoice.ownerId !== session.userId) return "forbidden";
  return "ok";
}

function getInvoice(invoices, session, id) {
  if (!session || !session.userId) throw new Error("not authenticated");
  const invoice = invoices.find((inv) => inv.id === id);
  if (!invoice) throw new Error("not found");
  if (invoice.ownerId !== session.userId) throw new Error("forbidden");
  return invoice;
}

function listInvoices(invoices, session) {
  if (!session || !session.userId) throw new Error("not authenticated");
  return invoices.filter((inv) => inv.ownerId === session.userId);
}

function deleteInvoice(invoices, session, id) {
  if (!session || !session.userId) throw new Error("not authenticated");
  const invoice = invoices.find((inv) => inv.id === id);
  if (!invoice) throw new Error("not found");
  if (invoice.ownerId !== session.userId && session.role !== "admin") {
    throw new Error("forbidden");
  }
  return invoices.filter((inv) => inv.id !== id);
}

